import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.G0y0PQA7.js";const n="/relio/shots/en/export-ddl-preview.png",s="/relio/shots/en/export-excel.png",x=JSON.parse('{"title":"Generate and export DDL","description":"","frontmatter":{},"headers":[],"relativePath":"en/quick/export.md","filePath":"en/quick/export.md"}'),i={name:"en/quick/export.md"};function l(d,e,c,h,p,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="generate-and-export-ddl" tabindex="-1">Generate and export DDL <a class="header-anchor" href="#generate-and-export-ddl" aria-label="Permalink to &quot;Generate and export DDL&quot;">​</a></h1><p>Generate the SQL (DDL) to run on a database, and documents such as Excel table documents, from your model.</p><h2 id="ddl" tabindex="-1">DDL <a class="header-anchor" href="#ddl" aria-label="Permalink to &quot;DDL&quot;">​</a></h2><ol><li>Open File › Export › DDL.</li><li>Choose the target database and version. The preview updates right away. Supported databases: PostgreSQL, MySQL, MariaDB, Oracle, SQL Server, Db2, H2, HSQLDB, SQLite, Informix, MS Access and standard SQL.</li><li>Choose what to generate (drop statements, tables, indexes, foreign keys, sequences, comments and so on), the encoding and the line break. Your choices are saved in the document and used next time.</li><li>Save it to a file. Click <strong>Open folder</strong> in the notice at the bottom right of the window to go straight to the file.</li></ol><figure class="shot" data-scene="export-ddl-preview"><img src="'+n+'" alt="DDL export dialog — choosing the target database and version and checking the preview" loading="lazy"><figcaption>DDL export dialog — choosing the target database and version and checking the preview</figcaption></figure><p>Syntax that the chosen version cannot run is removed or changed, with a warning. If there are errors that will make the DDL fail when run, the dialog says &quot;This document has n errors that make the DDL fail&quot;.</p><h2 id="other-exports" tabindex="-1">Other exports <a class="header-anchor" href="#other-exports" aria-label="Permalink to &quot;Other exports&quot;">​</a></h2><p>Choose the kind in File › Export.</p><ul><li><strong>Excel</strong> — Table documents (a Korean template is built in, as are English, Japanese and Chinese ones). ERMaster <code>.xls</code> templates also work, and the output is <code>.xlsx</code>.</li><li><strong>Image</strong> — PNG, JPG, BMP or SVG.</li><li><strong>HTML</strong> and <strong>Markdown</strong> — Documents you can read offline.</li><li><strong>DBML</strong>, <strong>Mermaid</strong> and <strong>Model JSON</strong> — For pasting into other tools. You can also copy straight to the clipboard.</li><li><strong>Java</strong> and <strong>Test data</strong> — Class sources and JPA entities; INSERT SQL and DBUnit XML.</li></ul><figure class="shot" data-scene="export-excel"><img src="'+s+'" alt="Excel export dialog — choosing the template and save location" loading="lazy"><figcaption>Excel export dialog — choosing the template and save location</figcaption></figure><p><strong>More</strong> → <a href="/relio/en/features/ddl">DDL</a> · <a href="/relio/en/features/export">Export</a></p>',11)])])}const m=t(i,[["render",l]]);export{x as __pageData,m as default};
